(function(root){'use strict';
function slots(day){const end=day===5||day===6?1340:1280,step=day>=1&&day<=4?90:60,result=[];for(let m=660;m<=end;m+=step)result.push(m);if(result.at(-1)!==end)result.push(end);return result;}
class FloorAlerts{
 constructor(options){this.options=options;this.seen=new Set();this.audio=null;this.timer=setInterval(()=>this.check(),15000);document.addEventListener('pointerdown',()=>this.unlock(),{passive:true});document.addEventListener('visibilitychange',()=>this.check());}
 async unlock(){try{const Audio=root.AudioContext||root.webkitAudioContext;if(!Audio)return;if(!this.audio)this.audio=new Audio();if(this.audio.state==='suspended')await this.audio.resume();}catch(_){} }
 sound(){try{if(!this.audio||this.audio.state!=='running')return;for(let i=0;i<3;i++){const o=this.audio.createOscillator(),g=this.audio.createGain(),at=this.audio.currentTime+i*.65;o.frequency.value=740;g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(.18,at+.03);g.gain.exponentialRampToValueAtTime(.001,at+.4);o.connect(g);g.connect(this.audio.destination);o.start(at);o.stop(at+.45);}}catch(_){} }
 check(at=this.options.now()){if(!this.options.isManager()||document.hidden||document.getElementById('managerFloorAlert'))return;const parts=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(at).map(p=>[p.type,p.value])),date=parts.year+'-'+parts.month+'-'+parts.day,day=new Date(date+'T12:00:00Z').getUTCDay(),minutes=Number(parts.hour)*60+Number(parts.minute),due=slots(day).filter(m=>m<=minutes&&minutes-m<5).at(-1);if(due===undefined)return;const key=date+'_'+due;if(this.seen.has(key))return;try{if(localStorage.getItem('fz_floor_alert_ack')===key)return;}catch(_){}this.show(key,due===slots(day).at(-1));}
 show(key='test',last=false){if(document.getElementById('managerFloorAlert'))return;const dialog=document.createElement('dialog');dialog.id='managerFloorAlert';dialog.innerHTML='<h2>MANAGER · CHECK FLOOR</h2><p>Walk the Floor and meet your customers.</p><p>Check every section, guest needs and table service.</p>'+(last?'<strong>LAST SEATING · Final Floor check</strong>':'')+'<button class="primary full">ACKNOWLEDGE · CHECK FLOOR</button>';document.body.appendChild(dialog);this.sound();const done=()=>{this.seen.add(key);if(key!=='test')try{localStorage.setItem('fz_floor_alert_ack',key);}catch(_){}dialog.close();dialog.remove();};dialog.querySelector('button').onclick=done;dialog.addEventListener('cancel',e=>{e.preventDefault();done();});dialog.showModal();}
}
FloorAlerts.slots=slots;root.FloorAlerts=FloorAlerts;if(typeof module!=='undefined')module.exports={slots};
})(globalThis);
